#[test]fn all104_actual_caller_fields_match_pre_damage_and_pre_acquisition_fixture(){let native=std::env::var("NATIVE_UPSTREAM_REACTION_ORACLE").ok().map(|p|std::fs::read_to_string(p).unwrap().lines().map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>());let mut h=2166136261u32;let mut n=0;for kind in 0..2{for s in 0..if kind==0{72}else{32}{let row=Fixture::new(kind,s).row();if let Some(native)=&native{assert_eq!(row,native[n],"actual104nativefieldwise kind{kind}/row{s}");}for value in row.as_object().unwrap().values(){if let Some(s)=value.as_str(){for &b in s.as_bytes(){h=(h^u32::from(b)).wrapping_mul(16777619);}}else{h=(h^(value.as_i64().unwrap()as u32)).wrapping_mul(16777619);}}n+=1;}}assert_eq!(n,104);assert_eq!(h,2016281248,"all104 actual native sorted-field values, including seeded raw hashes");}
